pub type SafeVec[T] = {
  data: *T;
  len: Int;
  cap: Int;
}
  invariant: self.len >= 0;
  invariant: self.cap >= self.len;

impl SafeVec[T] {
  fn new(capacity: Int) -> SafeVec[T]
    requires: capacity > 0;
    ensures: result.len == 0;
    ensures: result.cap == capacity;
  {
    return SafeVec[T]{ data: null, len: 0, cap: capacity };
  }

  fn push(self: &mut Self, value: T)
    requires: self.len < self.cap;
    ensures: self.len == self@pre.len + 1;
  {
    self.len = self.len + 1;
  }

  fn pop(self: &mut Self) -> T
    requires: self.len > 0;
    ensures: self.len == self@pre.len - 1;
  {
    self.len = self.len - 1;
    return self.data[self.len];
  }

  fn len(self: &Self) -> Int
    ensures: result == self.len;
    ensures: result >= 0;
  { return self.len; }
}

fn main() -> Int {
  var v = SafeVec[Int]::new(10);
  v.push(10);
  v.push(20);
  v.push(30);
  v.pop();
  return v.len();
}
